query:
UPDATE blog_posts 
SET content = REGEXP_REPLACE(content, '^# [^\n]+\n+', '')
WHERE content REGEXP '^# ';
SELECT id, slug, SUBSTRING(content, 1, 200) as content_start FROM blog_posts ORDER BY id DESC LIMIT 5;

